int main(){int t;scanf("%d",&t);while(t--){int n,m,k,d;scanf("%d %d %d %d",&n,&m,&k,&d);
 vector<long long> cost(n);vector<long long> dp(m);vector<int> a(m);
 for(int i=0;i<n;i++){for(int j=0;j<m;j++)scanf("%d",&a[j]);
  deque<int> q;dp[0]=1;q.push_back(0);
  for(int j=1;j<m;j++){while(q.front()<j-d-1)q.pop_front();
   dp[j]=a[j]+1+dp[q.front()];
   while(!q.empty()&&dp[q.back()]>=dp[j])q.pop_back();q.push_back(j);}
  cost[i]=dp[m-1];}
 long long s=0,best=LLONG_MAX;
 for(int i=0;i<n;i++){s+=cost[i];if(i>=k)s-=cost[i-k];if(i>=k-1)best=min(best,s);}
