int main(){int t;scanf("%d",&t);while(t--){int n,m;ll v;scanf("%d %d %lld",&n,&m,&v);vector<ll> a(n),P(n+1,0);
 for(int i=0;i<n;i++){scanf("%lld",&a[i]);P[i+1]=P[i]+a[i];}
 vector<int> pf(n+1,0),sf(n+1,0);ll s=0;
 for(int i=0;i<n;i++){s+=a[i];pf[i+1]=pf[i];if(s>=v){pf[i+1]++;s=0;}}
 s=0;for(int j=n-1;j>=0;j--){s+=a[j];sf[j]=sf[j+1];if(s>=v){sf[j]++;s=0;}}
 if(pf[n]<m){puts("-1");continue;}
 ll best=0;
 for(int i=0;i<=n;i++){ // j: largest index >= i with sf[j] >= m-pf[i]
  int need=m-pf[i];int lo=i,hi=n,r=-1;
  while(lo<=hi){int md=(lo+hi)/2;if(sf[md]>=need){r=md;lo=md+1;}else hi=md-1;}
  if(r>=i)best=max(best,P[r]-P[i]);}
 printf("%lld\n",best);}}

