typedef long long ll;const ll MOD=998244353;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int n,m;scanf("%d %d",&n,&m);vector<vector<pair<int,ll>>> byR(m+1);ll P=1;
 for(int i=0;i<n;i++){int l,r;ll p,q;scanf("%d %d %lld %lld",&l,&r,&p,&q);
  ll pr=p*pw(q,MOD-2)%MOD, np=(q-p)*pw(q,MOD-2)%MOD;P=P*np%MOD;
  byR[r].push_back({l,pr*pw(np,MOD-2)%MOD});}
 vector<ll> dp(m+1,0);dp[0]=1;
 for(int r=1;r<=m;r++)for(auto&[l,w]:byR[r])dp[r]=(dp[r]+dp[l-1]*w)%MOD;
 printf("%lld\n",P*dp[m]%MOD);}

